CREATE TYPE public.app_role AS ENUM ('admin','attendant','barber');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role AND active) $$;
CREATE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND active) $$;
CREATE POLICY read_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.assign_owner_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='douglas13091982@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT(user_id) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_barbershop_owner AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_owner_role();
CREATE TABLE public.barbershop_records (kind text NOT NULL CHECK(kind IN ('clients','appointments','barbers','services','testimonials','gallery','holidays','siteSettings','themeSettings')), id text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kind,id));
GRANT SELECT ON public.barbershop_records TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.barbershop_records TO authenticated; GRANT ALL ON public.barbershop_records TO service_role;
ALTER TABLE public.barbershop_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_catalog ON public.barbershop_records FOR SELECT TO anon,authenticated USING (kind IN ('services','barbers','testimonials','gallery','holidays','siteSettings','themeSettings') AND (kind NOT IN ('services','barbers','testimonials') OR data->>'active'='true'));
CREATE POLICY staff_read ON public.barbershop_records FOR SELECT TO authenticated USING(public.is_staff());
CREATE POLICY staff_write ON public.barbershop_records FOR ALL TO authenticated USING(public.is_staff() AND (kind IN ('clients','appointments') OR public.has_role(auth.uid(),'admin'))) WITH CHECK(public.is_staff() AND (kind IN ('clients','appointments') OR public.has_role(auth.uid(),'admin')));
CREATE FUNCTION public.busy_slots() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('barberId',data->>'barberId','serviceId',data->>'serviceId','date',data->>'date','time',data->>'time','status',data->>'status')), '[]'::jsonb) FROM public.barbershop_records WHERE kind='appointments' AND data->>'status' NOT IN ('cancelled','no_show') AND data->>'date'>=to_char(now() AT TIME ZONE 'America/Sao_Paulo','YYYY-MM-DD') $$;
REVOKE ALL ON FUNCTION public.busy_slots() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.busy_slots() TO anon,authenticated;
CREATE TABLE public.booking_receipts (token uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id text NOT NULL, client_id text NOT NULL, created_at timestamptz DEFAULT now());
GRANT ALL ON public.booking_receipts TO service_role; ALTER TABLE public.booking_receipts ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.book_appointment(input jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s jsonb; b jsonb; settings jsonb; wh jsonb; cid text; aid text := gen_random_uuid()::text; tok uuid := gen_random_uuid(); ap jsonb; cl jsonb; slot timestamp; start_min integer; end_min integer; duration integer;
BEGIN
IF length(trim(input->>'name')) NOT BETWEEN 2 AND 150 OR length(regexp_replace(input->>'phone','[^0-9]','','g')) NOT BETWEEN 10 AND 15 THEN RAISE EXCEPTION 'Nome ou telefone inválido.'; END IF;
SELECT data INTO s FROM public.barbershop_records WHERE kind='services' AND id=input->>'serviceId' AND data->>'active'='true';
SELECT data INTO b FROM public.barbershop_records WHERE kind='barbers' AND id=input->>'barberId' AND data->>'active'='true';
SELECT data INTO settings FROM public.barbershop_records WHERE kind='siteSettings' AND id='main';
IF s IS NULL OR b IS NULL OR NOT (b->'serviceIds' ? (input->>'serviceId')) THEN RAISE EXCEPTION 'Serviço ou barbeiro indisponível.'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(input->>'barberId'),hashtext(input->>'date'));
slot := ((input->>'date')||' '||(input->>'time'))::timestamp;
IF slot < (now() AT TIME ZONE 'America/Sao_Paulo') + make_interval(hours=>(settings->>'minAdvanceHours')::int) OR slot::date > (now() AT TIME ZONE 'America/Sao_Paulo')::date + (settings->>'maxAdvanceDays')::int THEN RAISE EXCEPTION 'Data fora do período permitido.'; END IF;
SELECT w INTO wh FROM jsonb_array_elements(b->'workingHours') w WHERE (w->>'dayOfWeek')::int=extract(dow FROM slot)::int AND w->>'active'='true';
IF wh IS NULL OR b->'daysOff' ? (input->>'date') OR EXISTS(SELECT 1 FROM public.barbershop_records WHERE kind='holidays' AND data->>'date'=input->>'date' AND data->>'active'='true') THEN RAISE EXCEPTION 'Dia indisponível.'; END IF;
duration := (s->>'duration')::int; start_min := extract(hour FROM slot)::int*60+extract(minute FROM slot)::int; end_min:=start_min+duration;
IF (input->>'time')::time < (wh->>'start')::time OR slot+make_interval(mins=>duration) > slot::date+(wh->>'end')::time OR (start_min-(extract(hour FROM (wh->>'start')::time)::int*60+extract(minute FROM (wh->>'start')::time)::int)) % greatest((settings->>'intervalMinutes')::int,1) <> 0 THEN RAISE EXCEPTION 'Horário indisponível.'; END IF;
IF EXISTS(SELECT 1 FROM public.barbershop_records a LEFT JOIN public.barbershop_records svc ON svc.kind='services' AND svc.id=a.data->>'serviceId' WHERE a.kind='appointments' AND a.data->>'barberId'=input->>'barberId' AND a.data->>'date'=input->>'date' AND a.data->>'status' NOT IN ('cancelled','no_show') AND slot < ((a.data->>'date')||' '||(a.data->>'time'))::timestamp+make_interval(mins=>coalesce((svc.data->>'duration')::int,30)) AND slot+make_interval(mins=>duration)>((a.data->>'date')||' '||(a.data->>'time'))::timestamp) THEN RAISE EXCEPTION 'Este horário acabou de ser reservado. Escolha outro.'; END IF;
SELECT id,data INTO cid,cl FROM public.barbershop_records WHERE kind='clients' AND regexp_replace(data->>'phone','[^0-9]','','g')=regexp_replace(input->>'phone','[^0-9]','','g') LIMIT 1;
IF cl->>'blocked'='true' THEN RAISE EXCEPTION 'Entre em contato com a barbearia para agendar.'; END IF;
IF cid IS NULL THEN cid:=gen_random_uuid()::text; cl:=jsonb_build_object('id',cid,'name',left(input->>'name',150),'phone',left(input->>'phone',30),'email',left(coalesce(input->>'email',''),200),'notes','','blocked',false,'totalSpent',0,'totalVisits',0,'createdAt',now()); INSERT INTO public.barbershop_records VALUES('clients',cid,cl,now()); END IF;
ap:=jsonb_build_object('id',aid,'clientId',cid,'barberId',input->>'barberId','serviceId',input->>'serviceId','date',input->>'date','time',input->>'time','status','pending','notes',left(coalesce(input->>'notes',''),2000),'paymentStatus','pending','paymentMethod','','amountPaid',0,'cancelReason','','createdAt',now());
INSERT INTO public.barbershop_records VALUES('appointments',aid,ap,now()); INSERT INTO public.booking_receipts(token,appointment_id,client_id) VALUES(tok,aid,cid);
RETURN jsonb_build_object('token',tok);
END $$;
REVOKE ALL ON FUNCTION public.book_appointment(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.book_appointment(jsonb) TO anon,authenticated;
CREATE FUNCTION public.booking_receipt(receipt_token uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('appointment',a.data,'client',jsonb_build_object('id',c.id,'name',c.data->>'name')) FROM public.booking_receipts r JOIN public.barbershop_records a ON a.kind='appointments' AND a.id=r.appointment_id JOIN public.barbershop_records c ON c.kind='clients' AND c.id=r.client_id WHERE r.token=receipt_token AND r.created_at>now()-interval '90 days' $$;
REVOKE ALL ON FUNCTION public.booking_receipt(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.booking_receipt(uuid) TO anon,authenticated;